using System;using System.IO;using System.Text;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {static class LauncherNativeState {
 public static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=32};
 public static T Read<T>(string file,Func<T> empty){LauncherMaintenance.NoReparse(file);if(!File.Exists(file))return empty();if(new FileInfo(file).Length>2097152)throw new Exception("本地记录超出大小限制，未覆盖。");try{return Json.Deserialize<T>(File.ReadAllText(file,new UTF8Encoding(false,true)));}catch{throw new Exception("本地记录损坏，未覆盖："+Path.GetFileName(file));}}
 public static void Write(string file,object value){LauncherMaintenance.NoReparse(file);Directory.CreateDirectory(Path.GetDirectoryName(file));byte[] bytes=Encoding.UTF8.GetBytes(Json.Serialize(value));if(bytes.Length>2097152)throw new Exception("本地记录超过容量限制。");string temp=file+".new-"+Guid.NewGuid().ToString("N");try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}LauncherMaintenance.NoReparse(file);if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static T Locked<T>(string file,Func<T> work){string key=DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(file).ToUpperInvariant()));using(var mutex=new Mutex(false,"Local\\OrangeState-"+key)){bool held=false;try{try{held=mutex.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new Exception("本地记录正被其他窗口处理，请稍后重试。");return work();}finally{if(held)mutex.ReleaseMutex();}}}
}}
